/* Additive navigation only. Original animation code and timing remain unchanged. */
(()=>{const ids=['apollo','surveyor','opportunity','spirit','viking','insight'];const link=document.createElement('a');link.href='/explore/';link.className='fieldbook-link';link.textContent='Open the interactive fieldbook ›';link.setAttribute('aria-label','Continue to the interactive mission fieldbook');const style=document.createElement('style');style.textContent='.fieldbook-link{position:fixed;right:20px;bottom:78px;z-index:39;background:#d9e6b6;color:#15211e;border:1px solid #94a87b;padding:12px 17px;border-radius:25px;font:11px Arial,sans-serif;box-shadow:0 4px 20px #0003}.fieldbook-link:focus-visible{outline:3px solid #fff;outline-offset:4px}body.locked .fieldbook-link{display:none}@media(max-width:680px){.fieldbook-link{right:12px;bottom:84px;font-size:10px;padding:11px 14px}}';document.head.append(style);document.body.append(link);const menu=document.querySelector('#menu');if(menu){const item=document.createElement('a');item.href='/explore/';item.textContent='Interactive fieldbook ›';menu.append(item);}let current='';function update(){const slide=document.querySelector('.wheel-present .reel-slide.is-active');const id=ids[Number(slide?.dataset.mission)];if(id){current=id;link.href='/explore/#mission/'+id;}const inOrbit=document.querySelector('.orbital-stories')?.getBoundingClientRect();if(!inOrbit||inOrbit.bottom<0||inOrbit.top>innerHeight)link.href='/explore/';}addEventListener('scroll',update,{passive:true});})();
